#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

struct Vec {
  vector<ll> a;
  Vec(int size = 30) : a(size, 0) {}
};

struct Mat {
  vector<vector<ll>> a;
  Mat(int size = 30) : a(size, vector<ll>(size, 0)) {}
};

ll n, k;

int digit_sum_mod(ll x) {
  if (x < k) return x;
  return (x + digit_sum_mod(x / k)) % k;
}

vector<Mat> baseM, invM;
vector<vector<Mat>> expE, invE;
Vec current;

Mat multiply(const Mat& A, const Mat& B) {
  int size = A.a.size();
  Mat C(size);
  for (int i = 0; i < size; ++i) {
    for (int j = 0; j < size; ++j) {
      C.a[i][j] = 0;
      for (int p = 0; p < size; ++p) {
        C.a[i][j] = (C.a[i][j] + (A.a[i][p] % MOD) * (B.a[p][j] % MOD)) % MOD;
      }
      C.a[i][j] = (C.a[i][j] % MOD + MOD) % MOD;
    }
  }
  return C;
}

Vec multiply(const Mat& A, const Vec& v) {
  int size = A.a.size();
  Vec res(size);
  for (int i = 0; i < size; ++i) {
    res.a[i] = 0;
    for (int j = 0; j < size; ++j) {
      res.a[i] = (res.a[i] + (v.a[j] % MOD) * (A.a[i][j] % MOD)) % MOD;
    }
    res.a[i] = (res.a[i] % MOD + MOD) % MOD;
  }
  return res;
}

void preprocess() {
  int size = k;
  expE.assign(200, vector<Mat>(40, Mat(size)));
  invE.assign(200, vector<Mat>(40, Mat(size)));

  for (int i = 0; i < k; ++i) {
    expE[0][i] = baseM[i];
    invE[0][i] = invM[i];
  }

  int depth = 0;
  ll temp = n;
  while (temp > 0) {
    ++depth;
    temp /= k;
  }

  for (int level = 1; level <= depth; ++level) {
    expE[level][0] = expE[level-1][0];
    invE[level][0] = invE[level-1][0];

    for (int idx = 1; idx < k; ++idx) {
      expE[level][0] = multiply(expE[level-1][idx], expE[level][0]);
      invE[level][0] = multiply(invE[level][0], invE[level-1][idx]);
    }

    for (int idx = 1; idx < k; ++idx) {
      Mat temp1 = multiply(expE[level][idx-1], invE[level-1][idx-1]);
      expE[level][idx] = multiply(expE[level-1][idx-1], temp1);

      Mat temp2 = multiply(invE[level][idx-1], invE[level-1][idx-1]);
      invE[level][idx] = multiply(expE[level-1][idx-1], temp2);
    }
  }
}

Vec recursive_solve(ll num, Vec v, int level) {
  if (num == 0) return v;
  int w = digit_sum_mod(num / k);
  v = recursive_solve(num / k, v, level + 1);
  for (int i = 0; i < num % k; ++i) {
    v = multiply(expE[level][(w + i) % k], v);
  }
  return v;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  cin >> n >> k;

  baseM.resize(k, Mat(k));
  invM.resize(k, Mat(k));
  current = Vec(k);

  for (int i = 0; i < k; ++i) {
    current.a[i] = 1;
    for (int j = 0; j < k; ++j) {
      for (int l = 0; l < k; ++l) {
        if (j == l) {
          baseM[i].a[j][l] = 1;
          invM[i].a[j][l] = 1;
        } else if (j == i) {
          baseM[i].a[j][l] = 1;
          invM[i].a[j][l] = -1;
        } else {
          baseM[i].a[j][l] = 0;
          invM[i].a[j][l] = 0;
        }
      }
    }
  }

  preprocess();
  current = recursive_solve(n, current, 0);

  ll total = 0;
  for (int i = 0; i < k; ++i) {
    total = (total + current.a[i]) % MOD;
  }
  total = ((total - 1) % MOD + MOD) % MOD;

  while (total % (k - 1) != 0) {
    total = (total + MOD) % (MOD * (k - 1));
  }

  cout << total / (k - 1) << '\n';
  return 0;
}
